"command": "python3 - <<'PY'
import pickle
import json

with open('outputs/identification_results_v2.pkl', 'rb') as f:
    results = pickle.load(f)

summary = {}
for dataset_name, dataset_results in results.items():
    summary[dataset_name] = {}
    for cell_name, res in dataset_results.items():
        summary[dataset_name][cell_name] = {
            'rmse_voltage_V': round(res['rmse_voltage'], 4),
            'rmse_temperature_C': round(res['rmse_temperature'], 2),
            'identified_params': {k: float(v) if hasattr(v, 'item') else v for k, v in res['identified_params'].items() if k in ['Rs_neg', 'Rs_pos', 'Ds_neg_ref', 'Ds_pos_ref', 'k_neg_ref', 'k_pos_ref', 'R_ohm', 'h_conv', 'Ea_k']}
        }

with open('outputs/summary_results.json', 'w') as f:
    json.dump(summary, f, indent=2)

print("Summary saved.")
for ds, cells in summary.items():
    print(f"\n{ds}:")
    for cell, data in cells.items():
        print(f"  {cell}: V_RMSE={data['rmse_voltage_V']}V, T_RMSE={data['rmse_temperature_C']}°C")
PY"
